145				return fmt.Errorf("clusters[%d]: 字段 %q 不能为空或只含空白", i, "id")
146			}
147			if _, dup := seen[c.ID]; dup {
148				return fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, c.ID)
149			}
150			seen[c.ID] = struct{}{}
151			if err := validateTagKeys(i, c.Tags); err != nil {
152				return err
153			}
154		}
155		if err := validateConditionKeys("include", in.Include); err != nil {
156			return err
157		}
158		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
159			return err
160		}
161		return nil
162	}
