270				}
271				keys := make([]string, 0, len(tm))
272				for k := range tm {
273					keys = append(keys, k)
274				}
275				sort.Strings(keys)
276				for _, k := range keys {
277					if k == "" {
278						return nil, fmt.Errorf("集群 %q 的标签键不能为空", id)
279					}
280					sv, ok := tm[k].(string)
281					if !ok {
282						return nil, fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k)
283					}
284					tags[k] = sv
